         'attempt_ids', jsonb_agg(id ORDER BY id),
         'source_sha256', '06c9627234683325116fdd8f9f9ac186ced50b94be2a0d6d9f33a9e72cf16122',
         'render_artifact', jsonb_build_array('.artifacts/release-work-2026-09-24/claude/renders/doc9361-p56.png'),
         'render_sha256', jsonb_build_array('1bcdc7580f2e0368a38301cb528b189d6c916979fabee14526ac19f4e3000a0d'),
         'missing', jsonb_build_array(jsonb_build_object('what', 'Binding-clipped line endings within the operative notification; six literal[illegible]markers, not reconstructed.', 'last_printed_block_id', 2511402, 'resumes_block_id', 2511402)),
         'owner_decision', jsonb_build_object(
